**How it works**

- The border is a conic-gradient layer clipped by `overflow: hidden` on a 1.5px-padded pill, so only a rotating rim shows. The layer is square at 160% width (`aspect-ratio: 1`), so rotation never exposes a corner on wide buttons.
- GSAP rotates that single layer with `rotation: 360`, `ease: 'none'`, `repeat: -1` — transform only, no gradient/box-shadow/width tweening. `will-change: transform` is scoped to that one element.
- Hover brightens a static blurred aura; pointer-down scales the surface to 0.98 over 100ms. `quickTo` reuses one tween per property, and hover listeners are skipped on touch devices.

```tsx
import { useRef, type ReactNode } from 'react';
import { useGSAP } from '@gsap/react';
import gsap from 'gsap';

gsap.registerPlugin(useGSAP);

export function AnimatedBorderCTA({ children, href = '#' }: { children: ReactNode; href?: string }) {
  const root = useRef<HTMLSpanElement>(null);
  const ring = useRef<HTMLSpanElement>(null);
  const aura = useRef<HTMLSpanElement>(null);
  const surface = useRef<HTMLAnchorElement>(null);

  useGSAP(() => {
    const mm = gsap.matchMedia();

    mm.add('(prefers-reduced-motion: no-preference)', () => {
      gsap.to(ring.current!, { rotation: 360, duration: 4, ease: 'none', repeat: -1, force3D: true });

      const auraOpacity = gsap.quickTo(aura.current!, 'opacity', { duration: 0.25, ease: 'power2.out' });
      const press = gsap.quickTo(surface.current!, 'scale', { duration: 0.1, ease: 'power2.out' });
      const shell = root.current!;

      const enter = () => auraOpacity(0.8);
      const leave = () => { auraOpacity(0.45); press(1); };
      const down = () => press(0.98);
      const up = () => press(1);

      if (window.matchMedia('(hover: hover) and (pointer: fine)').matches) {
        shell.addEventListener('pointerenter', enter);
        shell.addEventListener('pointerleave', leave);
      }
      shell.addEventListener('pointerdown', down);
      window.addEventListener('pointerup', up);

      return () => {
        shell.removeEventListener('pointerenter', enter);
        shell.removeEventListener('pointerleave', leave);
        shell.removeEventListener('pointerdown', down);
        window.removeEventListener('pointerup', up);
      };
    });

    mm.add('(prefers-reduced-motion: reduce)', () => {
      gsap.set(ring.current!, { rotation: 0, clearProps: 'willChange' });
      gsap.set(aura.current!, { opacity: 0.45, clearProps: 'willChange' });
      gsap.set(surface.current!, { scale: 1, clearProps: 'all' });
    });

    return () => mm.revert();
  }, { scope: root });

  return (
    <span className="cta-shell" ref={root}>
      <span className="cta-aura" ref={aura} aria-hidden="true" />
      <span className="cta-frame">
        <span className="cta-ring" ref={ring} aria-hidden="true" />
        <a className="cta-surface" ref={surface} href={href}>{children}</a>
      </span>
    </span>
  );
}
```

